[
  {
    "severity": "P0毁容级",
    "category": "other",
    "description": "左侧头像图标「表单 AI」使用了工业蓝色调，严重偏离「酱园琥珀」设计语言中明确要求的酱色（深棕红）与琥珀色系。",
    "suggestion": "将蓝色背景图标修改为酱色或琥珀色系，保持品牌色调统一。"
  },
  {
    "severity": "P1明显",
    "category": "ua-default-style",
    "description": "底部输入框「问我任何经营问题...」保留了明显的浏览器原生 textarea/input 边框观感，表现为较细且生硬的描边，与上方卡片的柔和阴影和圆角不协调。",
    "suggestion": "移除原生边框，采用「酱园琥珀」的圆角卡片样式，增加微弱内阴影或琥珀色柔和描边。"
  },
  {
    "severity": "P1明显",
    "category": "inconsistency",
    "description": "底部输入框的圆角半径（约 4px-8px）与上方消息气泡及操作标签的圆角（约 16px+）严重不统一，底部呈现直角化倾向。",
    "suggestion": "增加底部输入区圆角，使其与整体「圆角卡片」语言的一致性。"
  },
  {
    "severity": "P2瑕疵",
    "category": "layout-overflow",
    "description": "顶部导航标题「帮我登记一条采购单：供...」发生截断，未充分利用顶部空间且影响语义完整性。",
    "suggestion": "减小标题字号或优化省略策略，优先保证关键业务信息的展示。"
  },
  {
    "severity": "P2瑕疵",
    "category": "misalign",
    "description": "AI 回复中的状态标签「查询业务记录」相比上方正文「我来帮你登记」有轻微的左侧内缩位移，导致左侧视觉对齐线不规整。",
    "suggestion": "统一 AI 消息内所有元素的左内边距，确保视觉垂直对齐。"
  },
  {
    "severity": "P2瑕疵",
    "category": "contrast",
    "description": "主卡片内「准入评审中」的琥珀色下划线与其下方的极淡黄色背景对比度略低，在强光环境下可能难以辨识为可点击状态。",
    "suggestion": "加深琥珀色下划线的浓度或略微调整点击态的底色。"
  },
  {
    "severity": "P1明显",
    "category": "ua-default-style",
    "description": "状态标签内的绿色勾选图标「√」疑似为操作系统原生表情符号或默认图标，观感廉价且与「印章元素」的设计主旨冲突。",
    "suggestion": "替换为具有「酱园琥珀」风格的线性图标或带有手工印章质感的图形元素。"
  }
]
